/bin/zsh -lc "python3 -c 'import json; from pathlib import Path; p=Path(\"analysis.ipynb\"); n=json.loads(p.read_text());
for c in n[\"cells\"]:
 src=\"\".join(c.get(\"source\",[]));
 if \"NU = 1.004e-6\" in src:
  src=src.replace(\"NU = 1.004e-6  # 20C, TODO use temp\", \"L = 0.60\\ndef nu_water(T_C):\\n    # Kinematic viscosity (m"'^2/s), from temperature-dependent dynamic viscosity'"\\n    # (Vogel correlation) and liquid-water density (standard polynomial), 0–40 C.\\n    T = T_C + 273.15\\n    mu = 2.414e-5 * 10**(247.8 / (T - 140.0))\\n    rho = 1000 * (1 - ((T_C + 288.9414) / (508929.2 * (T_C + 68.12963))) * (T_C - 3.9863)**2)\\n    return mu / rho\")
 if \"df[\\'Re\\'] = df.speed_m_s * d / NU\" in src:
  src=src.replace(\"df[\\'Re\\'] = df.speed_m_s * d / NU\", \"df = df[df.run "'!= 17].copy()  # flagged zero drift; anomalous force'"\\nd = df.diameter_mm / 1000\\ndf[\\'nu_m2_s\\'] = df.water_temp_c.map(nu_water)\\ndf[\\'Re\\'] = df.speed_m_s * d / df.nu_m2_s\")
  c[\"source\"]=src.splitlines(keepends=True)
p.write_text(json.dumps(n, indent=1)+\"\\\\n\")'"

